Web Workers:
// main.js
const worker = new Worker("worker.js");
worker.postMessage({ cmd: "compute", data: [1, 2, 3] });
worker.onmessage = (e) => console.log(e.data);

// worker.js
self.onmessage = (e) => {
    const result = e.data.data.reduce((a, b) => a + b, 0);
    self.postMessage(result);
};

