Fetch API:
async function getData() {
    try {
        const res = await fetch("/api/data", {
            headers: { Accept: "application/json" }
        });
        if (!res.ok) throw new Error("HTTP " + res.status);
        const data = await res.json();
        console.log(data);
    } catch(err) { console.error(err); }
}

